; rows.asm -- chapter 26: every Y
; generated by gen26.py
        INCLUDE "msx.inc"
        OUTPUT "rows.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; A sprite of 16 x 16, a block, at X = 120, given every Y from 0 to
; 255, one a frame, after the paper.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $3800        ; the sprite patterns
        ld hl, patterns
        ld c, VDP_DATA
        ld b, 168
        otir
        VRAM_WRITE $1B00        ; sprite 0: Y 0, X 120, a block, black
        xor a
        out (VDP_DATA), a
        ld a, 120
        out (VDP_DATA), a
        ld a, 16
        out (VDP_DATA), a
        ld a, 1
        out (VDP_DATA), a
        ld a, $D0
        out (VDP_DATA), a       ; sprite 1: the end of the table
        VDP_REG 1, $C2          ; the display on, sprites of 16 x 16
        in a, (VDP_CTRL)        ; F cleared: the first wait is for a whole paper
        ld e, 0                 ; Y
next:   call frame              ; the paper has ended
m0:     VRAM_WRITE $1B00        ; 40  sprite 0's Y
        ld a, e                 ;  5
        out (VDP_DATA), a       ; 12
m1:     inc e
        jr nz, next             ; 256 frames
done:   jr done

; frame: wait for the end of the paper: F, bit 7 of the status, read with the
; interrupts off (chapter 19)
frame:  in a, (VDP_CTRL)
        rla
        jr nc, frame
        ret
patterns:
        db $3C, $66, $6E, $76, $66, $66, $3C, $00
        db $18, $38, $18, $18, $18, $18, $7E, $00
        db $3C, $66, $06, $0C, $30, $60, $7E, $00
        db $3C, $66, $06, $1C, $06, $66, $3C, $00
        db $03, $07, $05, $07, $02, $1F, $3F, $37
        db $37, $37, $07, $06, $06, $06, $0E, $0E
        db $C0, $E0, $A0, $E0, $40, $F8, $FC, $EC
        db $EC, $EC, $E0, $60, $60, $60, $70, $70
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $00, $0F, $1F, $3F, $7C, $78, $70, $70
        db $70, $70, $78, $7C, $3F, $1F, $0F, $00
        db $00, $F0, $F8, $FC, $3E, $1E, $0E, $0E
        db $0E, $0E, $1E, $3E, $FC, $F8, $F0, $00
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $FF, $FF, $FF, $FF, $FF, $FF, $FF, $FF
        db $F8, $F0, $F8, $DC, $8E, $07, $03, $01
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
